\set ON_ERROR_STOP on
create function public.assert(ok boolean,msg text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',msg;end if;end$$;
insert into auth.users values('00000000-0000-4000-a000-000000000001'),('00000000-0000-4000-a000-000000000002'),('00000000-0000-4000-a000-000000000003');
insert into public.stores(id,name,password_hash) values('11111111-1111-4111-a111-111111111111','測試門市',extensions.crypt('test-only-password',extensions.gen_salt('bf',4)));
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000001',false);
select public.assert(not public.join_store('11111111-1111-4111-a111-111111111111',null),'reject null password');
select public.assert(not public.join_store('11111111-1111-4111-a111-111111111111','wrong'),'reject wrong password');
select public.assert(not public.is_member('11111111-1111-4111-a111-111111111111'),'wrong password no membership');
select public.assert(public.join_store('11111111-1111-4111-a111-111111111111','test-only-password'),'correct login');
select public.apply_operation('aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaa1','11111111-1111-4111-a111-111111111111','22222222-2222-4222-a222-222222222222','add',0,'{"name":"茶葉蛋","expiry":"2027-01-01","photo":"11111111-1111-4111-a111-111111111111/22222222-2222-4222-a222-222222222222.jpg"}');
select public.apply_operation('aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaa1','11111111-1111-4111-a111-111111111111','22222222-2222-4222-a222-222222222222','add',0,'{}');
select public.assert((select count(*)=1 from public.products),'retry no duplicate');
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000002',false);
select public.assert((select count(*)=0 from public.products),'nonmember cannot read');
do $$begin perform public.apply_operation(gen_random_uuid(),'11111111-1111-4111-a111-111111111111','22222222-2222-4222-a222-222222222222','delete',1,'{}');raise exception 'FAIL unauthorized write';exception when others then if sqlerrm<>'ACCESS_DENIED' then raise;end if;end$$;
select public.assert(public.join_store('11111111-1111-4111-a111-111111111111','test-only-password'),'second device joins');
select public.assert((select count(*)=1 from public.products),'second device sees product');
select public.apply_operation('aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaa2','11111111-1111-4111-a111-111111111111','22222222-2222-4222-a222-222222222222','edit',1,'{"name":"雞蛋","expiry":"2027-01-02"}');
do $$begin perform public.apply_operation(gen_random_uuid(),'11111111-1111-4111-a111-111111111111','22222222-2222-4222-a222-222222222222','delete',1,'{}');raise exception 'FAIL missed conflict';exception when others then if sqlerrm<>'CONFLICT' then raise;end if;end$$;
do $$begin perform public.apply_operation(gen_random_uuid(),'11111111-1111-4111-a111-111111111111','22222222-2222-4222-a222-222222222222','delete',null,'{}');raise exception 'FAIL null version bypass';exception when others then if sqlerrm<>'CONFLICT' then raise;end if;end$$;
select public.apply_operation('aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaa3','11111111-1111-4111-a111-111111111111','22222222-2222-4222-a222-222222222222','delete',2,'{}');
select public.apply_operation('aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaa4','11111111-1111-4111-a111-111111111111','22222222-2222-4222-a222-222222222222','undo',3,'{}');
select public.assert((select deleted_at is null and version=4 from public.products),'undo restores version');
insert into storage.objects(bucket_id,name) values('expiry-photos','11111111-1111-4111-a111-111111111111/22222222-2222-4222-a222-222222222222.jpg');
select public.assert((select count(*)=1 from storage.objects),'member reads photo');
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000003',false);
select public.assert((select count(*)=0 from storage.objects),'nonmember cannot read photo');
do $$declare ok boolean;begin for i in 1..9 loop ok=public.join_store('11111111-1111-4111-a111-111111111111','wrong');end loop;ok=public.join_store('11111111-1111-4111-a111-111111111111','test-only-password');perform public.assert(not ok,'login throttled');end$$;
reset role;
update public.stores set epoch=epoch+1;
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000002',false);
select public.assert(not public.is_member('11111111-1111-4111-a111-111111111111'),'password rotation revokes session');
select public.assert((select count(*)=0 from public.products),'revoked cannot read rows');
select public.assert((select count(*)=0 from storage.objects),'revoked cannot read photos');
reset role;
select 'PASS: password, membership, RLS, idempotency, shared edits, conflicts, undo, photo privacy, throttling, revocation' as result;
